import java.util.*;
public class Test {
    static <T extends Comparable<T>> T findMax(List<T> list) {
        T max = list.get(0);
        for (T item : list) {
            if (item.compareTo(max) > 0) {
                max = item;
            }
        }
        return max;
    }
    public static void main(String[] args) {
        List<Integer> list = Arrays.asList(3, 7, 2, 9, 1);
        System.out.println(findMax(list));
    }
},9,Compilation error,3,7

